+  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
+  float m = l - c / 2, r = 0, g = 0, b = 0;
+  if (h < 60) { r = c; g = x; }
+  else if (h < 120) { r = x; g = c; }
+  else if (h < 180) { g = c; b = x; }
+  else if (h < 240) { g = x; b = c; }
+  else if (h < 300) { r = x; b = c; }
+  else { r = c; b = x; }
+  return rgb565((r + m) * 255, (g + m) * 255, (b + m) * 255);
