33	static const uint16_t C_DIM = rgb565(0x55, 0x55, 0x55), C_SEP = rgb565(0x44, 0x44, 0x44);
34	static const uint16_t C_RULE = rgb565(0x1e, 0x1e, 0x1e);
35	static const uint16_t C_BOXBG = rgb565(0x0a, 0x0a, 0x0a);
36	static const uint16_t ACCENTS[4] = {rgb565(0x38, 0xbd, 0xf8), rgb565(0xf5, 0x9e, 0x0b),
