static const uint16_t C_BLACK = 0x0000, C_WHITE = 0xFFFF;
static const uint16_t C_GHOST = rgb565(0x88, 0x88, 0x88), C_TITLE = rgb565(0x77, 0x77, 0x77);
static const uint16_t C_DIM = rgb565(0x55, 0x55, 0x55), C_SEP = rgb565(0x44, 0x44, 0x44);
static const uint16_t C_RULE = rgb565(0x1e, 0x1e, 0x1e);
