// ------------------------------------------------------------------ data
struct Quote {
  String idx, content, context, date, specific, container, cat;
  std::vector<String> tags;
};
static std::vector<Quote> quotes;
static int curQuote = 0;

static void addFallback(const char* idx, const char* content, const char* ctx, const char* date,
                        const char* specific, const char* container, const char* cat,
                        std::initializer_list<const char*> tags) {
  Quote q;
  q.idx = idx; q.content = content; q.context = ctx; q.date = date;
  q.specific = specific; q.container = container; q.cat = cat;
  for (auto t : tags) q.tags.push_back(t);
  quotes.push_back(q);
}

static void loadFallbackQuotes() {
  quotes.clear();
  addFallback("6",
    "Nỗi sợ lớn nhất của một người đàn ông chính là nước mắt đàn bà. Bản năng của phái mạnh là bao bọc, che chở chứ không phải giẫm đạp, hủy hoại. Bởi thế, đàn ông luôn tránh nói lời chia tay vì không dám đối diện với nước mắt, sợ làm tổn thương người phụ nữ của anh ta. Cũng vì lẽ đó mà trong Series Friends, anh chàng Chandler đã phải năm lần bảy lượt tìm không gian, thời điểm thích hợp nhưng vẫn không thể nói lời tạm biệt với người tình Janice. Vậy tại sao người phụ nữ - vốn được coi là phái yếu lại có thể mạnh mẽ cắt đứt một cuộc tình vốn đã chết trong trái tim đối phương? Vì họ sợ cảm giác bị thương hại. Vì trong tình thế này, nếu cứ cố chấp tiếp tục, tất cả những thương yêu mà đàn bà trao đi chỉ có thể đổi lấy lòng thương hại của người bạn tình hảo tâm, nhân đạo, ưa làm việc thiện nguyện. Nhưng đằng sau quyết định chia ly tưởng chừng dứt khoát luôn là lời cầu khẩn thầm thì ‘Anh ơi anh ở lại’.",
    "Backdrop: Suy ngẫm về sự yếu lòng, bản năng che chở của đàn ông và nỗi sợ bị thương hại của đàn bà trong tình yêu.",
    "2021~2023", "Đàn ông thích mèo, đàn bà yêu chó", "Spiderum - Linh Vũ", "writing",
    {"#Heartbroken", "#Love", "#Wisdom", "#Psychology"});
  addFallback("1", "Static, hum, tum, needle drops,\nSpinning, echo, time just stops.",
    "Vinyl Angel acoustic fiction. A tactile couplet evoking ambient tape hiss.", "2025-07",
    "Vinyl Angel", "Koi no Koe", "music", {"#Music", "#Acoustic", "#VinylAngel"});
  addFallback("2", "Familiar chords fill up the room,\nWrapped inside this faded tomb.",
    "Second couplet of Vinyl Angel narrative suite.", "2025-07",
    "Vinyl Angel", "Koi no Koe", "music", {"#Music", "#Memory", "#Nostalgia"});
}

static String jstr(JsonVariantConst o, const char* a, const char* b = nullptr) {
  JsonVariantConst v = o[a];
  if (v.isNull() && b) v = o[b];
  if (v.isNull()) return "";
  return v.as<String>();
}

static bool fetchQuotes() {
  WiFiClientSecure cli;
  cli.setInsecure();
  HTTPClient http;
  http.setTimeout(12000);
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  if (!http.begin(cli, API_URL)) return false;
  int code = http.GET();
  if (code != 200) {
    Serial.printf("[api] HTTP %d\n", code);
    http.end();
    return false;
  }
  String body = http.getString();
  http.end();
  JsonDocument doc;
  if (deserializeJson(doc, body)) return false;
  std::vector<Quote> fresh;
  auto parseOne = [&](JsonVariantConst o) {
    Quote q;
    q.idx = jstr(o, "idx");
    q.content = jstr(o, "content", "main_content");
    if (q.content.length() == 0) return;
    q.context = jstr(o, "context");
    q.date = jstr(o, "date", "effectiveDate");
    q.specific = jstr(o, "specific", "specificName");
    q.container = jstr(o, "container", "containerName");
    q.cat = jstr(o, "cat", "category");
    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
    for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
      String s = t.as<String>();
      if (!s.startsWith("#")) s = "#" + s;
      q.tags.push_back(s);
    }
    fresh.push_back(q);
  };
  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
  else parseOne(doc.as<JsonVariantConst>());
  if (fresh.empty()) return false;
  quotes = fresh;
  Serial.printf("[api] loaded %d quotes\n", (int)quotes.size());
  return true;
}

// ------------------------------------------------------------------ utf-8
static std::u16string u8to16(const String& s) {
  std::u16string o;
  const uint8_t* p = (const uint8_t*)s.c_str();
  size_t n = s.length();
  for (size_t i = 0; i < n;) {
    uint8_t c = p[i];
    uint32_t cp;
    int len;
    if (c < 0x80) { cp = c; len = 1; }
    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
    else { i++; continue; }
    if (i + len > n) break;
    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
    i += len;
    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
  }
  return o;
}

// ------------------------------------------------------------------ paging (port of buildPrescriptPages)
struct Line { std::u16string t; bool just; };
struct Page { std::vector<Line> lines; bool ctx; };

static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }

static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
  std::u16string w;
  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
  for (char16_t c : s) {
    if (c == '\n') { flush(); tok.push_back(u"\n"); }
    else if (isWS(c)) flush();
    else w.push_back(c);
  }
  flush();
}

static std::u16string trim16(const std::u16string& s) {
  size_t a = 0, b = s.size();
  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
  return s.substr(a, b - a);
}

static bool isWriting(const String& cat) {
  String c = cat; c.trim(); c.toLowerCase();
  return c == "writing" || c == "bài viết" || c == "baiviet";
}

static std::vector<Page> buildPages(const Quote& q) {
  std::vector<Page> pages;
  std::u16string content = trim16(u8to16(q.content));
  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
  std::vector<std::u16string> tok;
  tokenize(content, tok);
  bool writing = isWriting(q.cat);
  size_t ti = 0;
  int pageNum = 0;
  while (ti < tok.size()) {
    pageNum++;
    bool first = pageNum == 1;
    std::vector<std::u16string> pl;
    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
      int budget = MAX_CHARS;
      if (first && ln == 1) budget = MAX_CHARS - 1;
      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
      std::u16string cur;
      while (ti < tok.size()) {
        const std::u16string& nt = tok[ti];
        if (nt == u"\n") { ti++; break; }
        if (cur.empty()) { cur = nt; ti++; }

